import{_ as e,o as t,c as i,ag as r}from"./chunks/framework.BZohXCq9.js";const g=JSON.parse('{"title":"CI 明明被触发，为什么同步任务却直接跳过","description":"复盘 rules:changes 与 source fingerprint 不一致造成的空跑、漏同步和重复 MR，并给出 artifact contract 驱动的修复方法","frontmatter":{"title":"CI 明明被触发，为什么同步任务却直接跳过","description":"复盘 rules:changes 与 source fingerprint 不一致造成的空跑、漏同步和重复 MR，并给出 artifact contract 驱动的修复方法","tags":["GitLab CI","CI/CD","Fingerprint","SDK","问题复盘"],"date":"2026/07/20"},"headers":[],"relativePath":"linux/ci-trigger-fingerprint-contract.md","filePath":"linux/ci-trigger-fingerprint-contract.md","lastUpdated":1784519165000}'),n={name:"linux/ci-trigger-fingerprint-contract.md"};function s(c,a,l,o,p,d){return t(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="ci-明明被触发-为什么同步任务却直接跳过" tabindex="-1">CI 明明被触发，为什么同步任务却直接跳过 <a class="header-anchor" href="#ci-明明被触发-为什么同步任务却直接跳过" aria-label="Permalink to &quot;CI 明明被触发，为什么同步任务却直接跳过&quot;">​</a></h1><p>一条 CI job 被 <code>rules:changes</code> 触发，进入脚本后却发现 source fingerprint 没变化，于是直接退出。表面看只是浪费了一次 runner，实际更危险：某些文件变化可能触发 job，却永远不会进入同步结果；另一些无关文件又可能制造重复 MR。</p><p>问题不在 YAML 或 Python 单独哪一边，而在两套“什么会改变产物”的定义没有对齐。</p><h2 id="现场-去重优化反而制造新问题" tabindex="-1">现场：去重优化反而制造新问题 <a class="header-anchor" href="#现场-去重优化反而制造新问题" aria-label="Permalink to &quot;现场：去重优化反而制造新问题&quot;">​</a></h2><p>目标原本很合理：只有 SDK 真正变化时，才向下游仓库同步并创建 MR。方案使用两层门禁：</p><ol><li>CI 的 <code>rules:changes</code> 决定 job 是否启动；</li><li>同步脚本计算 source fingerprint，决定是否真正执行。</li></ol><p>第一版实现的问题是，两层输入集合不同。</p><p>例如 CI 可能把整份 <code>.gitlab-ci.yml</code>、同步脚本和 examples 都列为 trigger；fingerprint 却只包含库源码。于是出现：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CI 判断“需要同步”</span></span>
<span class="line"><span>  → job 启动</span></span>
<span class="line"><span>  → fingerprint 判断“SDK 没变”</span></span>
<span class="line"><span>  → job 直接退出</span></span></code></pre></div><p>反过来，如果某个真正影响库产物的路径只进入 fingerprint、没有进入 <code>rules:changes</code>，job 根本不会启动。</p><h2 id="根因-没有定义-artifact-contract" tabindex="-1">根因：没有定义 Artifact Contract <a class="header-anchor" href="#根因-没有定义-artifact-contract" aria-label="Permalink to &quot;根因：没有定义 Artifact Contract&quot;">​</a></h2><p>真正要同步的不是“仓库里看起来相关的文件”，而是能够改变目标 SDK artifact 的输入集合。</p><p>可以把它写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Artifact = Build(actual_sources, public_headers, build_options, required_scripts)</span></span></code></pre></div><p>CI trigger 集合 <code>T</code> 和 fingerprint 集合 <code>F</code> 都应该由这份合同推导：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T ≈ F ≈ 会改变目标 artifact bytes 或公开合同的文件集合</span></span></code></pre></div><p>不要求两者在语法上完全相同，但语义必须一致。</p><h2 id="第二次踩坑-为了保险-把范围又放大了" tabindex="-1">第二次踩坑：为了保险，把范围又放大了 <a class="header-anchor" href="#第二次踩坑-为了保险-把范围又放大了" aria-label="Permalink to &quot;第二次踩坑：为了保险，把范围又放大了&quot;">​</a></h2><p>修完第一轮 mismatch 后，一个常见反应是“那就多包含一些路径”。结果 examples 和整份 CI 文件又被放进 trigger/fingerprint。</p><p>这会重新制造无效同步。示例程序只生成独立 executable，并不进入共享库 source list；CI 里修改 unrelated job，也不会改变 SDK bytes。它们不应该因为“在同一目录附近”就被纳入 artifact contract。</p><h2 id="修复方法-从构建图反推输入" tabindex="-1">修复方法：从构建图反推输入 <a class="header-anchor" href="#修复方法-从构建图反推输入" aria-label="Permalink to &quot;修复方法：从构建图反推输入&quot;">​</a></h2><p>最终保留的输入类型只有：</p><ul><li>SDK 的公开头文件；</li><li>共享库/静态库真正编译的源码；</li><li>决定 source list 或编译选项的 CMake 文件；</li><li>确实影响产物的依赖构建脚本；</li><li>用于保证 artifact 可用性的必要 smoke 脚本。</li></ul><p>同步脚本本身、examples、整份 CI 配置都从正常 source fingerprint 中移除。需要手动刷新时，保留显式 <code>force-sync</code> 或 test mode，而不是污染日常触发集合。</p><h2 id="怎样验证不是-看起来对齐" tabindex="-1">怎样验证不是“看起来对齐” <a class="header-anchor" href="#怎样验证不是-看起来对齐" aria-label="Permalink to &quot;怎样验证不是“看起来对齐”&quot;">​</a></h2><p>这类修复至少需要四种检查：</p><h3 id="_1-trigger-fingerprint-对照表" tabindex="-1">1. Trigger/Fingerprint 对照表 <a class="header-anchor" href="#_1-trigger-fingerprint-对照表" aria-label="Permalink to &quot;1. Trigger/Fingerprint 对照表&quot;">​</a></h3><p>逐项回答每个路径是否会改变 artifact，以及它是否同时被 trigger 和 fingerprint 覆盖。</p><h3 id="_2-fingerprint-确定性" tabindex="-1">2. Fingerprint 确定性 <a class="header-anchor" href="#_2-fingerprint-确定性" aria-label="Permalink to &quot;2. Fingerprint 确定性&quot;">​</a></h3><p>相同文件内容、不同扫描顺序必须得到同一个 hash。路径排序、文件边界和空文件都应有稳定编码。</p><h3 id="_3-正反样本" tabindex="-1">3. 正反样本 <a class="header-anchor" href="#_3-正反样本" aria-label="Permalink to &quot;3. 正反样本&quot;">​</a></h3><ul><li>修改 public header：job 应触发，fingerprint 应变化；</li><li>修改库源码：两者都应变化；</li><li>修改 example：默认不应同步；</li><li>修改无关 CI job：默认不应同步；</li><li>强制模式：即使 hash 相同也应按显式意图执行。</li></ul><h3 id="_4-轻量语法验证" tabindex="-1">4. 轻量语法验证 <a class="header-anchor" href="#_4-轻量语法验证" aria-label="Permalink to &quot;4. 轻量语法验证&quot;">​</a></h3><p>YAML、脚本语法、diff whitespace 和 fingerprint determinism 都应在提交前完成，避免把逻辑 review 和基础语法错误混在一起。</p><h2 id="这类问题为什么值得单独写" tabindex="-1">这类问题为什么值得单独写 <a class="header-anchor" href="#这类问题为什么值得单独写" aria-label="Permalink to &quot;这类问题为什么值得单独写&quot;">​</a></h2><p>CI 去重不是“少跑几个 job”的小优化。它在定义跨仓库交付边界：什么变化必须传播，什么变化不应该制造下游噪声。</p><p>如果这份边界只存在于两段彼此独立的配置里，迟早会漂移。更稳的做法是先定义 artifact contract，再让 trigger、fingerprint、同步内容和测试共同引用同一个概念。</p><p>参考：<a href="https://docs.gitlab.com/ci/yaml/" target="_blank" rel="noreferrer">GitLab <code>rules:changes</code> 与 CI/CD YAML 官方说明</a>。</p>`,38)])])}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
